import { RadarChart } from '@dreadnought/ui/react';
const metrics = ['quality','coverage','latency'].map(id => ({id,label:id,domain:[0,100] as const}));
const series = [{id:'a',label:'A',values:{quality:80,coverage:70,latency:60}}];
export function Example() { return <RadarChart label="Сравнение" metrics={metrics} series={series} />; }

import { RadarChart } from '@dreadnought/ui/react';
const metrics = ['x','y','z'].map(id => ({id,label:id,domain:[0,100] as const}));
const series = [{id:'a',label:'A',values:{x:80,y:60,z:40}}];
export function Example() { return <RadarChart label="Сравнение" metrics={metrics} series={series}><RadarChart.Legend /><RadarChart.Plot tooltipContent={({defaultContent}) => <div>{defaultContent}</div>}>{({defaultContent}) => defaultContent}</RadarChart.Plot><RadarChart.Table /></RadarChart>; }
